------------ import ------------

function UIBambooConfirm:__init()
    self._okCb = nil
    self._cancelCb = nil
end

function UIBambooConfirm:__delete()
    self._okCb = nil
    self._cancelCb = nil
end

function UIBambooConfirm:Awake()
    self.controller.ClearCache = false

    SetButtonAction(self.BtnCancel, Bind(self, self.OnBtnCancel))
    SetButtonAction(self.BtnConfirm, Bind(self, self.OnBtnSure))
    SetButtonAction(self.Area, Bind(self, self.OnBtnCancel))
end

function UIBambooConfirm:ShowHUD(title, desc, desc2, isBoss, fV3, tV3, okCb, cancelCb, isHideBtn)
    CfUtils.FillText(self.Text, checkString(title))
    CfUtils.FillText(self.TextDesc, checkString(desc))
    CfUtils.FillText(self.TextTitle, checkString(desc2))
    CfUtils.FillText(self.TextTitle2, checkString(desc2))
    CfUtils.FillText(self.TextTitle1, checkString(desc2))

    CfUtils.PlayAnimator(self.AnimationRoot, checkBool(isBoss) and "Boss" or "NotBoss")
    self._okCb = okCb
    self._cancelCb = cancelCb
    self._fV3 = fV3
    self._tV3 = tV3
    self._isHideBtn = checkBool(isHideBtn)
    self:FillSelf()
end

function UIBambooConfirm:FillSelf()
    if self._isHideBtn then
        CfUtils.SetActive(self.ButtonGroup, false)
        return
    end

    if self._fV3 then 
        local v2 = CfUtils.WorldPosition2UIPosition(self._fV3, self.ButtonGroup)
        self.BtnConfirm.transform.anchoredPosition = v2
    end

    if self._tV3 then
        local v2 = CfUtils.WorldPosition2UIPosition(self._tV3, self.ButtonGroup)
        self.BtnCancel.transform.anchoredPosition = v2
    end
end

function UIBambooConfirm:FillTypeImage(path)
    if not path then 
        return
    end
    CfUtils.FillImage(self.Imgbuff, path)
end

function UIBambooConfirm:OnBtnSure()
    if self._okCb then
        self._okCb()
    end
    KTool.SafeDelete(self.controller.gameObject)
end

function UIBambooConfirm:OnBtnCancel()
    if self._cancelCb then
        self._cancelCb()
    end
    KTool.SafeDelete(self.controller.gameObject)
end

function UIBambooConfirm:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIBambooConfirm